10	const MAX_PORT = 65535;
11	const MAX_BODY_BYTES = 10000;
12	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
13	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
14	const JSON_TYPE = 'application/json; charset=utf-8';
15	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
