import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import net from 'node:net';
import http from 'node:http';

const label = process.argv[2];
const root = path.resolve(process.argv[3]);
const serverPath = path.join(root, label, 'server.mjs');
const work = fs.mkdtempSync(path.join(root, 'scratch', `w-${label}-`));

const results = [];
function check(name, ok, info = '') { results.push(`${ok ? 'PASS' : 'FAIL'} ${name} ${ok ? '' : info}`); }

function run(env, cwd = work) {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, [serverPath], { cwd, env: { ...process.env, ...env } });
    let out = '', err = '';
    let done = false;
    p.stdout.on('data', (d) => { out += d; const m = /listening on http:\/\/127\.0\.0\.1:(\d+)\n/.exec(out); if (m && !done) { done = true; resolve({ p, port: +m[1], out: () => out, err: () => err }); } });
    p.stderr.on('data', (d) => { err += d; });
    p.on('exit', (code) => { if (!done) { done = true; resolve({ code, out, err }); } });
  });
}

function raw(port, text) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = '';
    s.on('data', (d) => { buf += d; });
    s.on('end', () => resolve(buf));
    s.on('error', () => resolve(buf));
    s.write(text);
    setTimeout(() => { s.end(); }, 300);
  });
}

function req(port, method, p, { headers = {}, body } = {}) {
  return new Promise((resolve) => {
    const r = http.request({ host: '127.0.0.1', port, method, path: p, headers }, (res) => {
      let b = ''; res.on('data', (d) => { b += d; }); res.on('end', () => {
        let j; try { j = JSON.parse(b); } catch {}
        resolve({ status: res.statusCode, ct: res.headers['content-type'], body: b, json: j });
      });
    });
    r.on('error', (e) => resolve({ status: 'ERR ' + e.code }));
    if (body !== undefined) r.write(body);
    r.end();
  });
}
const J = { 'Content-Type': 'application/json' };
const post = (port, obj, headers = J) => req(port, 'POST', '/api/bookings', { headers, body: typeof obj === 'string' ? obj : JSON.stringify(obj) });
const B = (o = {}) => ({ room: 'Aurora', title: 'T', date: '2026-11-03', start: '09:00', end: '10:00', ...o });

// startup
let r = await run({ PORT: 'abc' }); check('PORT abc exit1', r.code === 1 && r.out === '' && r.err.split('\n').length === 2, JSON.stringify(r));
r = await run({ PORT: '65536' }); check('PORT 65536', r.code === 1, JSON.stringify(r));
r = await run({ PORT: ' 80' }); check('PORT space', r.code === 1, JSON.stringify(r));
r = await run({ PORT: 'abc', DATA_FILE: work }); check('PORT before data', r.code === 1 && !r.err.includes('data file'), JSON.stringify(r));
fs.mkdirSync(path.join(work, 'dir'));
r = await run({ PORT: '0', DATA_FILE: 'dir' }); check('data dir', r.code === 1 && r.err === 'cannot read data file dir\n', JSON.stringify(r));
fs.writeFileSync(path.join(work, 'empty.json'), '');
r = await run({ PORT: '0', DATA_FILE: 'empty.json' }); check('data empty', r.code === 1 && r.err === 'cannot read data file empty.json\n', JSON.stringify(r));
fs.writeFileSync(path.join(work, 'arr.json'), '[]');
r = await run({ PORT: '0', DATA_FILE: 'arr.json' }); check('data array', r.code === 1, JSON.stringify(r));
fs.writeFileSync(path.join(work, 'obj.json'), '{}');
r = await run({ PORT: '0', DATA_FILE: 'obj.json' }); check('data {}', r.code === 1, JSON.stringify(r));
// default file in cwd
fs.writeFileSync(path.join(work, 'bookings.json'), 'garbage');
r = await run({ PORT: '0', DATA_FILE: '' }); check('default bookings.json cwd', r.code === 1 && r.err === 'cannot read data file bookings.json\n', JSON.stringify(r));
