function run(env, cwd = work) {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, [serverPath], { cwd, env: { ...process.env, ...env } });
    let out = '', err = '';
    let done = false;
    p.stdout.on('data', (d) => { out += d; const m = /listening on http:\/\/127\.0\.0\.1:(\d+)\n/.exec(out); if (m && !done) { done = true; resolve({ p, port: +m[1], out: () => out, err: () => err }); } });
    p.stderr.on('data', (d) => { err += d; });
    p.on('exit', (code) => { if (!done) { done = true; resolve({ code, out, err }); } });
  });
}

function req(port, method, p, { headers = {}, body } = {}) {
  return new Promise((resolve) => {
    const r = http.request({ host: '127.0.0.1', port, method, path: p, headers }, (res) => {
      let b = ''; res.on('data', (d) => { b += d; }); res.on('end', () => {
        let j; try { j = JSON.parse(b); } catch {}
