x = await req(port, 'GET', '/api/bookings?date=2030%2D01-01'); check('decoded value', x.status === 200 && x.json.bookings.length === 4, x.body);
x = await req(port, 'GET', '/api/bookings?foo=1'); check('all list', x.status === 200 && x.json.bookings.length >= 8, x.body);
const all = x.json.bookings;
const key = (a) => a.date + a.start + ['Aurora','Borealis','Cosmos'].indexOf(a.room);
const sorted = [...all].sort((a, b) => key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0);
check('sort all', JSON.stringify(all) === JSON.stringify(sorted));
